use vstd::prelude::*;

verus! {
    // Multiply the polynomial p(x) by x: if p(x) has coefficients c[0..n),
    // we return q(x) = x·p(x) whose coefficients are [0, c[0], c[1], …, c[n-1]].
    //
    // Preconditions:
    //   - c.len() > 0
    //
    // Postconditions:
    //   - result.len() == c.len() + 1
    //   - result[0] == 0.0
    //   - for all j < c.len(): result[j+1] == c[j]
    fn legmulx(c: Vec<f32>) -> (result: Vec<f32>)
        requires
            c.len() > 0,
        ensures
            result.len() == c.len() + 1,
            result[0] == 0.0,
            forall |j: usize| j < c.len() ==> result[j+1] == c[j],
    {
        // We'll build up `res` by pushing elements.
        let mut res: Vec<f32> = Vec::new();
        // First coefficient of x·p(x) is always 0.0
        res.push(0.0);

        let mut i: usize = 0;
        // Loop invariant keeps track of how much we've filled.
        while i < c.len()
            invariant
                // We've processed i entries of c so far,
                i <= c.len(),
                // so res.len() == (i processed) + 1 initial = i+1
                res.len() == i + 1,
                // the first coefficient is still 0
                res[0] == 0.0,
                // for all j < i, we've pushed c[j] at res[j+1]
                forall |j: usize| j < i ==> res[j+1] == c[j],
            decreases c.len() - i,
        {
            // push the next coefficient
            res.push(c[i]);
            i = i + 1;
        }

        res
    }
}

